#!/bin/bash
# install_pins.sh   task 34 phase 1: Gen3PinData (generated by tools/elevation/bake_pins.py) + Gen3Elevation (user-pin block) + Gen3Relief (LEVEL 16)
# -> game + QA (the mod source already holds them), backup, patch. Commit is a separate step. Game must be closed.
set -eu
R=$HOME/Documents/Emerald
SRC=$HOME/Documents/battle-art-notquiteog
AS="$HOME/Library/Application Support"
GAME="$AS/pokemon-love2d/mods/BATTLE_ART_VOXEL_FORK"
QA="$AS/pokemon-love2d-rseqa/mods/BATTLE_ART_VOXEL_FORK"
B=$HOME/Documents/gen1recomp-modwork/backups/pins-20261027
[ -z "$(pgrep -f 'MacOS/love' || true)" ] || { echo "REFUSING: a game is running"; exit 2; }
python3 "$R/tools/elevation/bake_pins.py" "$SRC/lib/Gen3PinData.lua"
mkdir -p "$B"
for f in Gen3Elevation.lua Gen3Relief.lua; do
  cmp -s "$GAME/lib/$f" "$QA/lib/$f" || { echo "game/QA differ before install: $f"; exit 3; }
  cp "$GAME/lib/$f" "$B/$f"
done
for f in Gen3Elevation.lua Gen3Relief.lua Gen3PinData.lua; do
  luajit -bl "$SRC/lib/$f" /dev/null
  cp "$SRC/lib/$f" "$GAME/lib/$f"; cp "$SRC/lib/$f" "$QA/lib/$f"
  cmp -s "$SRC/lib/$f" "$GAME/lib/$f" && cmp -s "$SRC/lib/$f" "$QA/lib/$f" || { echo "MISMATCH $f"; exit 1; }
done
echo "installed, source = game = QA (Gen3Elevation Gen3Relief Gen3PinData); backup $B (revert = copy the two back, delete Gen3PinData)"
OWN_LIB_EXTRA="lib/Gen3PinData.lua lib/Gen3Elevation.lua lib/Gen3Relief.lua" bash "$R/tools/props/make_patch.sh"
